for _, fact in ipairs(rows) do
    local name, bossName, npcID, level, rank, model, drops = unpack(fact)
    local instance = (C.dungeonKnowledge and C.dungeonKnowledge[name]) or
        (C.raidKnowledge and C.raidKnowledge[name])
    if instance then
        local boss
        for _, candidate in ipairs(instance.bosses or {}) do
            if candidate.name == bossName then boss = candidate; break end
        end
        if not boss then
            boss = {name=bossName,loot={}}
            instance.bosses[#instance.bosses+1] = boss
        end
        boss.loot = boss.loot or {}
        if level > 0 then boss.level = level end
        if rank == 2 then boss.rare = true end
        if model > 0 then boss.displayID = model end
        if level > 0 then
            C.bossMetadata[name] = C.bossMetadata[name] or {}
            local previous = C.bossMetadata[name][bossName]
            C.bossMetadata[name][bossName] = {level,
                rank > 0 and rank or (previous and previous[2]) or 1,npcID}
        end
        local known = {}
        for _, item in ipairs(boss.loot) do known[item[1]]=item end
        for _, drop in ipairs(drops) do
            local item = known[drop[1]]
            if not item then
                item = {drop[1],"Item #"..drop[1],""}
                boss.loot[#boss.loot+1] = item
                known[drop[1]] = item
            end
            if drop[2] and drop[2] > 0 then item[5]=drop[2] end
        end
    end
end
-- Obsolete entries from an older Dalaran reference had no documented loot.
local dalaran = C.dungeonKnowledge and C.dungeonKnowledge["City of Dalaran"]
if dalaran then
    for index=#dalaran.bosses,1,-1 do
        local name=dalaran.bosses[index].name
        if name=="Mana Elemental" or name=="Mana Wraith" then
            table.remove(dalaran.bosses,index)
        end
    end
end
